@@ -0,0 +1,13 @@
+{
+	"useTabs": true,
+	"bracketSameLine": false,
+	"plugins": ["prettier-plugin-astro", "prettier-plugin-tailwindcss"],
+	"overrides": [
+		{
+			"files": "*.astro",
+			"options": {
+				"parser": "astro"
+			}
+		}
+	]
+}

@@ -0,0 +1,6 @@
+{
+	"[astro]": {
+		"editor.defaultFormatter": "esbenp.prettier-vscode"
+	},
+	"editor.formatOnSave": true
+}

@@ -0,0 +1,15 @@
+// @ts-check
+import { defineConfig } from "astro/config";
+import tailwindcss from "@tailwindcss/vite";
+import cloudflare from "@astrojs/cloudflare";
+
+export default defineConfig({
+	site: "https://jrwnnnn.me",
+	output: "server",
+	adapter: cloudflare({
+		remoteBindings: !process.env.CI,
+	}),
+	vite: {
+		plugins: [tailwindcss()],
+	},
+});

@@ -0,0 +1,8 @@
+import eslintPluginAstro from "eslint-plugin-astro";
+import tseslint from "typescript-eslint";
+
+export default [
+	{ ignores: [".astro/**", "dist/**", "node_modules/**", ".wrangler/**"] },
+	...tseslint.configs.recommended,
+	...eslintPluginAstro.configs.recommended,
+];

@@ -0,0 +1,8 @@
+@import "tailwindcss";
+body {
+	@apply flex min-h-dvh flex-col overflow-x-hidden;
+}
+
+main {
+	@apply grow px-5 py-20 md:px-20 lg:px-30;
+}

@@ -0,0 +1,11 @@
+{
+	"extends": "astro/tsconfigs/strict",
+	"include": [".astro/types.d.ts", "**/*", "./worker-configuration.d.ts"],
+	"exclude": ["dist"],
+	"compilerOptions": {
+		"paths": {
+			"@utils/*": ["./src/utils/*"]
+		},
+		"types": ["@cloudflare/workers-types"]
+	}
+}

@@ -0,0 +1,13 @@
+{
+	"compatibility_date": "2026-04-01",
+	"compatibility_flags": ["global_fetch_strictly_public", "nodejs_compat"],
+	"name": "scaffold",
+	"main": "@astrojs/cloudflare/entrypoints/server",
+	"assets": {
+		"directory": "./dist",
+		"binding": "ASSETS"
+	},
+	"observability": {
+		"enabled": true
+	}
+}

